index 0000000..a4a4333
--- /dev/null
+++ b/tests/google.ts
@@ -0,0 +1,131 @@
+import { createServer } from "node:http";
+import { createHash, randomUUID } from "node:crypto";
+import { exportJWK, generateKeyPair, SignJWT } from "jose";
+
+export async function startGoogle() {
+  const { privateKey, publicKey } = await generateKeyPair("RS256");
+  const other = await generateKeyPair("RS256");
+  const jwk = { ...(await exportJWK(publicKey)), kid: "test-google", alg: "RS256", use: "sig" };
+  let state: Record<string, any> = {};
+  let requests: { url: string; authorization?: string; body: string }[] = [];
+  const codes = new Map<string, URL>();
+  const server = createServer(async (req, res) => {
+    try {
+      const url = new URL(req.url!, "http://localhost:3101");
+      let body = "";
+      for await (const chunk of req) body += chunk;
+      const reply = (value: unknown, status = 200) => {
+        res.writeHead(status, { "content-type": "application/json" });
+        res.end(JSON.stringify(value));
+      };
+      if (url.pathname === "/control") {
+        if (req.method === "POST") {
+          const update = JSON.parse(body);
+          if (update.reset) {
+            state = {
+              sub: randomUUID(),
+              hd: "workspace.example",
+              email: "member@workspace.example",
+              directoryId: randomUUID(),
+              name: "Workspace Member",
+              emails: [{ address: "contact@example.org", type: "home" }],
+              phones: [{ value: "+1 555 0100", type: "mobile" }],
+              ...update,
+            };
+            requests = [];
+            codes.clear();
+          } else Object.assign(state, update);
+        }
+        return reply({ state, requests });
+      }
+      if (url.pathname === "/authorize") {
+        const authorization = new URL(JSON.parse(body).url);
+        const code = randomUUID();
+        codes.set(code, authorization);
+        const callback = new URL(authorization.searchParams.get("redirect_uri")!);
+        callback.searchParams.set("state", authorization.searchParams.get("state")!);
+        if (state.consentDenied) callback.searchParams.set("error", "access_denied");
+        else callback.searchParams.set("code", code);
+        return reply({ callback: callback.toString() });
+      }
+      const google = new URL(url.searchParams.get("url")!);
+      requests.push({ url: google.toString(), authorization: req.headers.authorization, body });
+      if (google.pathname === "/oauth2/v3/certs") return reply({ keys: [jwk] });
+      if (google.pathname === "/token") {
+        const params = new URLSearchParams(body);
+        if (params.get("grant_type") === "refresh_token") {
+          if (state.refreshDenied) return reply({ error: "invalid_grant" }, 400);
+          return reply({
+            access_token: "refreshed-google-token",
+            expires_in: 3600,
+            token_type: "Bearer",
+          });
+        }
+        const authorization = codes.get(params.get("code")!);
+        codes.delete(params.get("code")!);
+        const challenge = createHash("sha256")
+          .update(params.get("code_verifier") ?? "")
+          .digest("base64url");
+        if (
+          !authorization ||
+          challenge !== authorization.searchParams.get("code_challenge") ||
+          params.get("client_id") !== "test-client" ||
+          params.get("client_secret") !== "test-secret"
+        )
+          return reply({ error: "invalid_grant" }, 400);
+        const token = await new SignJWT({
+          sub: state.sub,
+          hd: state.hd,
+          email: state.email,
+          email_verified: state.emailVerified !== false,
+          ...state.claims,
+        })
+          .setProtectedHeader({ alg: "RS256", kid: "test-google" })
+          .setIssuer(state.issuer ?? "https://accounts.google.com")
+          .setAudience(state.audience ?? "test-client")
+          .setIssuedAt()
+          .setExpirationTime(state.expired ? "-1h" : "1h")
+          .sign(state.badSignature ? other.privateKey : privateKey);
+        return reply({
+          id_token: token,
+          access_token: "google-access-token",
+          refresh_token: "google-refresh-token",
+          expires_in: state.tokenExpiresIn ?? 3600,
+          token_type: "Bearer",
+          scope:
+            "openid email profile https://www.googleapis.com/auth/admin.directory.user.readonly",
+        });
+      }
+      if (state.credentialsDenied) return reply({ error: "invalid_token" }, 401);
+      if (google.pathname === "/v1/userinfo")
+        return reply({
+          sub: state.userinfoSub ?? state.sub,
+          hd: state.userinfoHd ?? state.hd,
+          email: state.email,
+          email_verified: state.emailVerified !== false,
+        });
+      if (google.pathname.startsWith("/admin/directory/v1/users/")) {
+        if (state.directoryStatus)
+          return reply({ error: { code: state.directoryStatus } }, state.directoryStatus);
+        const key = decodeURIComponent(google.pathname.split("/").at(-1)!);
+        if (![state.email, state.directoryId].includes(key))
+          return reply({ error: { code: 404 } }, 404);
+        return reply({
+          id: state.directoryId,
+          primaryEmail: state.directoryEmail ?? state.email,
+          name: { fullName: state.name },
+          ...(state.emails === null ? {} : { emails: state.emails }),
+          ...(state.phones === null ? {} : { phones: state.phones }),
+          suspended: true,
+          recoveryEmail: "private-recovery@example.org",
+        });
+      }
+      reply({ error: `Unexpected Google endpoint: ${google}` }, 500);
+    } catch (error) {
+      res.writeHead(500);
+      res.end(String(error));
+    }
+  });
+  await new Promise<void>((resolve) => server.listen(3101, "127.0.0.1", resolve));
+  return server;
+}
