@@ -0,0 +1,43 @@
+import { expect, test } from "@playwright/test";
+
+test.beforeEach(async ({ page, request }) => {
+  await request.post("http://127.0.0.1:3101/control", { data: { reset: true } });
+  await page.route("https://accounts.google.com/o/oauth2/v2/auth**", async (route) => {
+    const response = await request.post("http://127.0.0.1:3101/authorize", {
+      data: { url: route.request().url() },
+    });
+    const { callback } = await response.json();
+    await route.fulfill({ status: 302, headers: { location: callback } });
+  });
+});
+
+test("managed user sees their current Google profile and can sign out", async ({
+  page,
+  request,
+}) => {
+  await page.goto("/profile");
+  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
+  await page.getByRole("button", { name: "Sign in with Google" }).click();
+  await expect(page.getByRole("heading", { name: "Your Workspace profile" })).toBeVisible();
+  await expect(page.getByText("Workspace Member", { exact: true })).toBeVisible();
+  await expect(page.getByText("contact@example.org", { exact: true })).toBeVisible();
+  await expect(page.getByText("+1 555 0100", { exact: true })).toBeVisible();
+  await request.post("http://127.0.0.1:3101/control", { data: { name: "Updated in Google" } });
+  await page.reload();
+  await expect(page.getByText("Updated in Google", { exact: true })).toBeVisible();
+  const { requests } = await (await request.get("http://127.0.0.1:3101/control")).json();
+  expect(
+    requests
+      .filter((r: { url: string }) => r.url.includes("/directory/"))
+      .every(
+        (r: { url: string; authorization: string }) =>
+          new URL(r.url).searchParams.get("viewType") === "domain_public" &&
+          r.authorization === "Bearer google-access-token",
+      ),
+  ).toBe(true);
+  await expect(page.getByText("private-recovery@example.org")).toHaveCount(0);
+  await page.getByRole("button", { name: "Sign out", exact: true }).click();
+  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
+  await page.goto("/profile");
+  await expect(page.getByRole("button", { name: "Sign in with Google" })).toBeVisible();
+});
diff --git a/tests/start-app.mts b/tests/start-app.mts
