+// Loaded only by the test launcher, never by application code. Keep the actual
+// Google URLs and all OAuth/JWT checks; replace external network responses only.
+const originalFetch = globalThis.fetch;
+globalThis.fetch = (input, init) => {
+  const request = new Request(input, init);
+  const url = new URL(request.url);
+  if (
+    [
+      "oauth2.googleapis.com",
+      "www.googleapis.com",
+      "openidconnect.googleapis.com",
+      "admin.googleapis.com",
+    ].includes(url.hostname)
+  ) {
+    return originalFetch(
+      new Request(`http://127.0.0.1:3101/google?url=${encodeURIComponent(request.url)}`, request),
+    );
+  }
+  return originalFetch(input, init);
+};
